mapper.select:
SELECT t.id FROM auto_income_log l
JOIN daily_transaction t ON t.id = l.transaction_id AND t.user_id = l.user_id
WHERE l.user_id = #{userId} AND l.period_start = #{periodStart}

SELECT id, transaction_date AS date, type, category, amount, memo,
       is_recurring AS recurring, recurring_origin_id
FROM daily_transaction
WHERE user_id = #{userId} AND type = 'INCOME'
  AND category = #{category} AND amount = #{amount}
  AND transaction_date >= #{from} AND transaction_date <= #{to}
  AND id <> #{excludeId}
ORDER BY transaction_date, id

SELECT COUNT(*) FROM auto_income_log l
JOIN daily_transaction t ON t.id = l.transaction_id AND t.user_id = l.user_id
WHERE l.user_id = #{userId}

mapper.delete:
DELETE t FROM daily_transaction t
JOIN auto_income_log l ON l.transaction_id = t.id AND l.user_id = t.user_id
WHERE l.user_id = #{userId}
